const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const wh = $('webhook-entry').first().json;
const b = wh.body ?? wh;
const platform = b.platform;
let url = '';
if (platform === 'instagram')
  url = `https://graph.facebook.com/v21.0/${b.mediaId}/insights?metric=reach,likes,comments,shares,saved,video_views&access_token=${process.env.IG_ACCESS_TOKEN ?? ''}`;
else if (platform === 'facebook')
  url = `https://graph.facebook.com/v21.0/${b.mediaId}/insights?metric=post_impressions,post_engaged_users&access_token=${process.env.FB_PAGE_TOKEN ?? ''}`;
else throw new Error('unknown platform: ' + platform);
return [{ json: { productId: b.productId, platform, mediaId: b.mediaId, url } }];

const j = $input.first().json;
const raw = $input.first().json; // http item
const metrics = {};
for (const d of (raw.data ?? [])) {
  const v = (d.values ?? [])[0]?.value;
  metrics[d.name] = (typeof v === 'number') ? v : null; // never invent numbers
}
return [{ json: { productId: j.productId, platform: j.platform, mediaId: j.mediaId,
  metrics, collectedAt: new Date().toISOString(), state: 'ANALYZED',
  note: 'metrics are actual platform data only; missing → null (§16)' } }];
